/*
 * The vDSO's exported symbols and their version (Linux's arch/x86/entry/vdso/vdso.lds.S):
 * programs and C libraries look them up by name and "LINUX_2.6".
 */
LINUX_2.6 {
	global:
		clock_gettime;
		__vdso_clock_gettime;
		gettimeofday;
		__vdso_gettimeofday;
		getcpu;
		__vdso_getcpu;
		time;
		__vdso_time;
		clock_getres;
		__vdso_clock_getres;
	local: *;
};
